"""Build the home and category shells; catalog and interactions stay shared."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def shell(title,view,body):
    return f'''<!doctype html>
<html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f5f0e5"><meta name="description" content="霧雨魔法店：小游戏、趣味测试、虚构故事与影像创作工具。"><title>{title} · 霧雨魔法店</title><link rel="icon" href="images/logo.png"><link rel="stylesheet" href="css/vendor/fontawesome/css/all.min.css"><link rel="stylesheet" href="css/site.css"><script src="js/catalog.js" defer></script><script src="js/site.js" defer></script></head>
<body data-view="{view}"><div id="siteHeader"></div><main class="site-main" id="main">{body}</main><div id="siteFooter"></div></body></html>'''
home='''<section class="hero"><div><span class="eyebrow">魔法之森 / 一间不太正经的小店</span><h1>进来坐坐，<br>挑一件<em>有趣的事。</em></h1><p>玩一局小游戏，做一份奇怪的测试，<br>或者，把一张照片变成另一种记忆。<br>店里的东西有点杂，现在都替你分好了。</p><div class="hero-actions"><a href="explore.html" class="button">翻翻全部作品 <i class="fa-solid fa-arrow-right" aria-hidden="true"></i></a><a href="#new" class="text-link">看看店主的新作</a></div><form class="search-home" id="siteSearch" role="search"><label class="search-field"><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i><input id="homeQuery" aria-label="搜索作品" placeholder="想找什么？输入作品名或关键词" maxlength="100"></label><button type="submit">找一找 →</button></form></div><figure class="hero-art"><span class="art-label">KIRISAME'S / LITTLE SHOP</span><img src="images/logo.png" alt="戴着魔女帽、眨眼微笑的像素魔理沙" fetchpriority="high"><figcaption class="art-caption">A LITTLE MAGIC FOR YOUR DAY.</figcaption><span class="art-stamp">今日营业<br><small>随便看看就好</small></span></figure></section>
<section aria-labelledby="categoryTitle"><div class="section-heading"><div><span class="eyebrow">01 / THE SHELVES</span><h2 id="categoryTitle">先逛哪一间？</h2></div><a class="text-link" href="explore.html">全部作品 ↗</a></div><div id="categories" class="category-grid"></div></section>
<section id="new" aria-labelledby="featuredTitle"><div class="section-heading"><div><span class="eyebrow">02 / SHOPKEEPER'S PICKS</span><h2 id="featuredTitle">最近，店里多了这些</h2></div><span class="eyebrow">挑几件摆在门口</span></div><div class="featured-layout"><a href="zyms/DREAMCORE%20__%20旧核·梦核·怪核图片滤镜实验室.html" class="feature-memory"><img src="images/site/memory-cover.svg" alt="记忆信号：带有旧录像扫描线的绿色阈限走廊" width="900" height="560" loading="lazy"><div class="feature-copy"><span class="meta">NEW ARRIVAL / 影像创作</span><h3>记忆信号工作室</h3><p>旧核、梦核、怪核。一张照片的色彩、质感和失真，<br>都可以在这里慢慢调出来。</p><span class="text-link">进入 MEMORY SIGNAL ↗</span></div></a><div id="featuredList" class="featured-list"></div></div></section>
<aside class="shop-note"><span class="note-mark">店主的便笺</span><p>测试结果当个乐子就好，故事也都是编的。<br>遇到不好用的地方，或者想到新的玩法，欢迎来留句话。</p><a class="text-link" href="feedback.html">给店主捎句话 ↗</a></aside>'''
directory='''<header class="directory-head"><div class="breadcrumbs"><a href="index.html">小店首页</a> / 作品货架</div><span class="eyebrow" id="directoryEnglish"></span><h1 id="directoryTitle">作品货架</h1><p id="directoryDescription"></p></header><section aria-label="作品目录" id="resultsStart"><div class="directory-controls"><label class="search-field"><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i><input type="search" id="query" aria-label="搜索作品" placeholder="按名称或关键词查找" maxlength="100"></label><select id="categoryFilter" class="filter-select" aria-label="按用途分类"></select><span class="result-count" id="resultCount" role="status" aria-live="polite"></span></div><div class="tag-filters" id="tagFilters" role="group" aria-label="按主题筛选"></div><p class="category-disclaimer">作品按用途归类；测试与模拟内容仅供娱乐。部分作品含闪烁或模拟恐怖效果，请留意各页说明。</p><div class="work-grid" id="workGrid"></div><div class="empty-state" id="emptyState" hidden>这次没有找到合适的作品。<br><a href="explore.html">清除筛选，重新逛逛</a></div><nav class="pagination" id="pagination" aria-label="作品分页"></nav></section>'''
(ROOT/'index.html').write_text(shell('首页','home',home),encoding='utf-8')
for key,title in {'games':'游戏室','tests':'测试屋','stories':'故事角','tools':'工具与创作','explore':'全部作品'}.items():
    (ROOT/(key+'.html')).write_text(shell(title,key,directory),encoding='utf-8')
print('Built home and five directory pages')
